<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php';
require_once __DIR__ . '/db.php';
function e(mixed $value): string { return htmlspecialchars((string) ($value ?? ''), ENT_QUOTES, 'UTF-8'); }
$id = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]); $token = preg_replace('/[^a-f0-9]/i', '', (string) ($_GET['token'] ?? '')); $invoice = false;
if ($id && strlen($token) === 64) { try { $pdo = getDatabaseConnection(); $statement = $pdo->prepare('SELECT inv.*, i.event_type, i.target_event_date FROM invoices inv JOIN inquiries i ON i.id=inv.inquiry_id WHERE inv.id=? AND inv.public_token=?'); $statement->execute([$id, $token]); $invoice = $statement->fetch(); } catch (PDOException $exception) { error_log('LEGATO view invoice: ' . $exception->getMessage()); } }
if (!$invoice) http_response_code(404);
?>
<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Invoice | LEGATO Events &amp; Productions</title><script src="https://cdn.tailwindcss.com"></script><script>tailwind.config={theme:{extend:{colors:{obsidian:'#121212',charcoal:'#181818',line:'#282828',gold:'#D4AF37',ivory:'#F5F2EB'},fontFamily:{serif:['Playfair Display','serif'],sans:['Montserrat','sans-serif']}}}}</script><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap" rel="stylesheet"></head><body class="min-h-screen bg-[#121212] font-sans text-[#F5F2EB]"><main class="mx-auto flex min-h-screen max-w-3xl items-center px-5 py-10"><section class="w-full overflow-hidden rounded-2xl border border-[#D4AF37]/30 bg-[#181818] shadow-2xl"><?php if(!$invoice): ?><div class="p-10 text-center"><p class="font-mono text-xs uppercase tracking-[.18em] text-[#D4AF37]">Invoice unavailable</p><h1 class="mt-3 font-serif text-4xl">This invoice link is not valid.</h1><a class="mt-6 inline-block text-sm text-[#D4AF37] underline" href="index.php">Return home</a></div><?php else: ?><header class="border-b border-[#282828] bg-[#121212] px-6 py-7 sm:px-10"><img src="Assest/legato1.png" class="h-14 w-auto" alt="LEGATO Events &amp; Productions"><p class="mt-6 font-mono text-[10px] uppercase tracking-[.2em] text-[#D4AF37]">50% Downpayment Invoice</p><h1 class="mt-2 font-serif text-4xl">Your event reservation.</h1></header><div class="p-6 sm:p-10"><div class="grid gap-5 border-b border-[#282828] pb-6 text-sm sm:grid-cols-2"><p><span class="text-[#9CA3AF]">Customer</span><br><strong><?php echo e($invoice['client_name']); ?></strong></p><p><span class="text-[#9CA3AF]">Invoice</span><br><span class="font-mono text-[#D4AF37]"><?php echo e($invoice['invoice_number']); ?></span></p><p><span class="text-[#9CA3AF]">Event</span><br><?php echo e($invoice['event_type']); ?> · <?php echo e($invoice['target_event_date']); ?></p><p><span class="text-[#9CA3AF]">Issue / due date</span><br><?php echo e($invoice['created_at']); ?> · <?php echo e($invoice['due_date']); ?></p></div><dl class="mt-6 space-y-4 text-sm"><div class="flex justify-between"><dt class="text-[#9CA3AF]">Total event price</dt><dd>&#8369;<?php echo number_format((float)$invoice['total_amount'],2); ?></dd></div><div class="flex justify-between"><dt class="text-[#9CA3AF]">Required downpayment (50%)</dt><dd class="font-serif text-2xl text-[#D4AF37]">&#8369;<?php echo number_format((float)$invoice['amount_due'],2); ?></dd></div></dl><a class="mt-8 block rounded bg-[#D4AF37] px-5 py-4 text-center text-xs font-bold uppercase tracking-wider text-[#121212] transition hover:opacity-90" href="booking.php?invoice=<?php echo (int)$invoice['id']; ?>&token=<?php echo e($token); ?>#payment">Proceed to Downpayment</a><p class="mt-4 text-center text-xs leading-5 text-[#9CA3AF]">Please settle on or before the due date to secure your requested event date.</p></div><?php endif; ?></section></main></body></html>
